fn max(a: &Vec<i32>) -> usize {
    // Since the array is guaranteed to be non-empty, we can safely
    // initialize our "best so far" with the first element.
    let mut max_index = 0;
    let mut max_value = a[0];

    // Iterate over the rest of the array
    for i in 1..a.len() {
        let v = a[i];
        if v > max_value {
            max_value = v;
            max_index = i;
        }
    }

    max_index
}

